#!/usr/bin/env python3
"""Offline R13 installer. Its source code is embedded, with no download/pip stage."""
from __future__ import annotations
import argparse
import base64
import fcntl
import hashlib
import io
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile
import zipfile

PAYLOAD_SHA256 = 'e03c36d347ff00b59f23d98b8ccee48f90324e83ef438e74579310474bc1d389'
PAYLOAD_BASE64 = ''
DEFAULT_PYTHON = '/public/home/zhuziyuan/.venvs/paper3-hpc-cu121-offline/bin/python'
DEFAULT_M12_PLAN = '/public/home/zhuziyuan/projects/paper3/runs/r12_controlled_mechanism/plan.json'


def notice(event, **fields):
    print(json.dumps(dict(event=event, **fields), ensure_ascii=False, default=str), flush=True)


def _sha(data):
    return hashlib.sha256(data).hexdigest()


def install(home):
    data = base64.b64decode(PAYLOAD_BASE64, validate=True)
    if _sha(data) != PAYLOAD_SHA256:
        raise ValueError('Embedded package checksum failed; no code was applied')
    base = Path(home).expanduser().absolute() / 'paper3-round13'
    base.mkdir(parents=True, exist_ok=True)
    target = base / PAYLOAD_SHA256[:20]
    with (base / 'install.lock').open('a') as guard:
        fcntl.flock(guard, fcntl.LOCK_EX)
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            manifest = json.loads(archive.read('SOURCE_MANIFEST.json'))
            expected = manifest['files']
            if (len(data) > 5*1024*1024 or len(expected) > 100
                    or set(archive.namelist()) != set(expected) | {'SOURCE_MANIFEST.json'}):
                raise ValueError('Embedded source inventory differs')
            for name, proof in expected.items():
                rel = Path(name)
                if rel.is_absolute() or '..' in rel.parts or rel.as_posix() != name:
                    raise ValueError('Invalid source path')
                content = archive.read(name)
                if len(content) != proof['bytes'] or _sha(content) != proof['sha256']:
                    raise ValueError('Embedded source file differs: '+name)
            if target.exists():
                for name, proof in expected.items():
                    file = target / name
                    if file.is_symlink() or not file.is_file() or _sha(file.read_bytes()) != proof['sha256']:
                        raise ValueError('Installed immutable R13 package differs: '+name)
            else:
                stage = Path(tempfile.mkdtemp(prefix='.install-', dir=base))
                try:
                    for name in archive.namelist():
                        file = stage / name
                        file.parent.mkdir(parents=True, exist_ok=True)
                        file.write_bytes(archive.read(name))
                        file.chmod(0o700 if name.endswith('.sh') else 0o600)
                    os.rename(stage, target)
                finally:
                    if stage.exists():
                        shutil.rmtree(stage)
    notice('R13_CODE_INSTALLED', package=str(target), files=len(expected),
           payload_sha256=PAYLOAD_SHA256, old_rounds_changed=False)
    return target


# Appended after the shared offline-install prefix by build_parallel_delivery.py.
def main(argv=None):
    parser=argparse.ArgumentParser(description='R13 three independent GPU jobs; original scientific plan and checkpoints retained.',allow_abbrev=False)
    mode=parser.add_mutually_exclusive_group()
    mode.add_argument('--submit',action='store_true',help='replace verified pending R13 and reconcile three single-GPU jobs')
    mode.add_argument('--status',action='store_true',help='show all three jobs and scientific progress')
    mode.add_argument('--report',action='store_true',help='generate the common participant-level report')
    parser.add_argument('--home',type=Path,default=Path.home())
    parser.add_argument('--m12-plan',type=Path,default=Path(DEFAULT_M12_PLAN))
    parser.add_argument('--m12-package',type=Path)
    parser.add_argument('--output',type=Path)
    parser.add_argument('--python',default=DEFAULT_PYTHON)
    parser.add_argument('--role',choices=('pilot','development'),default='pilot')
    parser.add_argument('--no-observer',action='store_true')
    args=parser.parse_args(argv)
    notice('R13_THREE_JOBS_START',message='三作业程序已启动；原计划和断点保留，每作业1GPU/12CPU/64G。',jobs=3)
    package=install(args.home)
    sys.path.insert(0,str(package))
    from paper3r13.bootstrap import activate_paths
    activate_paths()
    from paper3r13 import runtime,parallel
    from paper3r13.common import load_plan
    suffix='r13_update_validity' if args.role=='pilot' else 'r13_update_validity_development'
    if args.output:
        output=args.output.expanduser().resolve()
    else:
        guess=args.m12_plan.expanduser().resolve().parent.parent/suffix
        if (guess/'plan.json').is_file():
            output=guess
        else:
            from paper3r13.native import _read
            output=(Path(_read(args.m12_plan)['root'])/'runs'/suffix).resolve()
    plan_path=output/'plan.json'
    if plan_path.is_file():
        plan=load_plan(plan_path)
        notice('R13_ORIGINAL_PLAN_REUSED',plan=plan_path,recipe_sha256=plan['recipe_sha256'],scientific_plan_changed=False)
    elif args.status or args.report:
        raise FileNotFoundError('R13 plan not found: '+str(plan_path))
    else:
        plan=runtime.prepare(args.m12_plan,output,package=package,python=args.python,role=args.role,
            m12_package=args.m12_package,partition='hpc_gpu1',cpus=12,memory='64G')
    if args.status:
        notice('R13_PARALLEL_STATUS',**parallel.status(plan_path))
        return 0
    if args.report:
        from paper3r13.report import generate_report
        notice('R13_REPORT',**generate_report(plan_path))
        return 0
    if not args.submit:
        launch=parallel.prepare_launch(plan_path,package=package)
        notice('R13_THREE_JOBS_PREPARED_ONLY',plan=plan_path,
            slots=[dict(slot=s['slot'],source_seed=s['source_seed'],tasks=len(s['task_keys'])) for s in launch['slots']],
            resources_per_job=launch['resources'],jobs_submitted=0,old_job_cancelled=False)
        return 0
    result=parallel.submit(plan_path,package=package)
    slots=result.get('slots',[])
    if slots and not args.no_observer:
        try:
            from paper3r13.parallel_observer import start
            notice('R13_PARALLEL_OBSERVER',**start(plan_path,package=package))
        except Exception as error:
            notice('R13_PARALLEL_OBSERVER_RETRY_NEEDED',error_type=type(error).__name__,training_affected=False)
    good={'ACKNOWLEDGED','EXISTING_JOB_PRESERVED','SCIENTIFIC_SHARD_COMPLETE'}
    ready=len(slots)==3 and all(s.get('status') in good for s in slots)
    notice('R13_THREE_JOBS_READY' if ready else 'R13_THREE_JOBS_RECONCILIATION_RESULT',
        plan=plan_path,submission=result,terminal_can_close=True,scientific_recipe_unchanged=True,
        original_rounds_R1_R11_M12_changed=False,
        message='三槽提交已核对；排队与运行请用 --status查看。' if ready else
          '请以各槽状态为准；再次执行同一命令只补缺槽，已运行作业及科学断点保留。')
    return 0 if ready or not slots else 2


if __name__=='__main__':
    try:
        raise SystemExit(main())
    except Exception as error:
        notice('R13_THREE_JOBS_ACTION_FAILED',error_type=type(error).__name__,message=str(error),
               existing_scientific_results_preserved=True)
        raise SystemExit(1)
